                var ms = document.getElementById('msgSpecInput');
                if (ms) decisions.msgSpec = parseInt(ms.value);
                var br = document.getElementById('bridgeInput');
                if (br) decisions.bridgeStrat = parseInt(br.value);
                var hr = document.getElementById('hostileInput');
                if (hr) decisions.hostileResp = parseInt(hr.value);
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var logos = 0;
            var ethos = 0;
            var pathos = 0;
            var ethics = 0;
            var ces = 0;
            var roundLabel = '';

            if (period === 1) {
                roundLabel = this._t('audience_board');

                if (d.scqaLead === 1) { ethos += 8; logos += 6; }
                else if (d.scqaLead === 2) { ethos -= 5; logos += 3; }
                else { ethos += 2; logos += 5; }

                if (d.govThought === 1) { logos += 10; ethos += 5; }
                else if (d.govThought === 2) { logos -= 4; ethos -= 4; }
                else { logos += 5; ethos += 2; }

                if (d.missAttr === 3) { ethos += 9; ethics += 5; logos += 4; }
                else if (d.missAttr === 1) { ethos -= 6; ethics -= 3; }
                else { ethos -= 2; logos += 2; }

                if (d.marginTreat === 1) { ethos += 4; ethics += 5; logos += 3; }
                else if (d.marginTreat === 2) { ethos += 1; ethics += 2; }
                else { ethics -= 12; ethos -= 6; }

                var v1s = this.VIZ_SCORES[d.viz1] || { accuracy: 0, framing: 0, ethos: 0, ethics: 0 };
                var v2s = this.VIZ_SCORES[d.viz2] || { accuracy: 0, framing: 0, ethos: 0, ethics: 0 };
                logos += Math.round((v1s.accuracy + v2s.accuracy) / 2);
                ethos += Math.round((v1s.ethos + v2s.ethos) / 2);
                pathos += Math.round((v1s.framing + v2s.framing) / 2);
                ethics += Math.round((v1s.ethics + v2s.ethics) / 2);

                logos = Math.max(0, Math.min(100, 50 + logos));
                ethos = Math.max(0, Math.min(100, 50 + ethos));
                pathos = Math.max(0, Math.min(100, 50 + pathos));
                ethics = Math.max(0, Math.min(100, 70 + ethics));

                ces = Math.round(logos * 0.35 + ethos * 0.30 + pathos * 0.15 + ethics * 0.20);
                ds.boardCES = ces;

            } else if (period === 2) {
                roundLabel = this._t('audience_employee');

                var ecVal = d.emotCal;
                if (ecVal >= 4 && ecVal <= 6) { pathos += 10; ethos += 5; }
                else if (ecVal >= 7 && ecVal <= 9) { ethos -= 8; pathos -= 3; }
                else if (ecVal === 10) { ethos -= 15; pathos -= 10; ethics -= 8; }
                else if (ecVal <= 3) { pathos += 4; ethos += 3; logos += 2; }

                var qaDirs = [d.layoffDir, d.targetDir, d.predictDir];
                var qaSpecs = [d.layoffSpec, d.targetSpec, d.predictSpec];
                var qaLogos = 0;
                var qaEthos = 0;
                var qaPathos = 0;

                for (var i = 0; i < 3; i++) {
                    if (qaDirs[i] >= 4) { qaEthos += 6; qaPathos += 4; }
                    else if (qaDirs[i] <= 2) { qaEthos -= 8; qaPathos -= 5; }
                    else { qaEthos += 1; }

                    if (qaSpecs[i] >= 4) { qaLogos += 5; qaEthos += 3; }
                    else if (qaSpecs[i] <= 2) { qaLogos -= 3; }
                    else { qaLogos += 1; }
                }

                logos += qaLogos;
                ethos += qaEthos;
                pathos += qaPathos;

                var evtId = ds.randomEvent || 6;
                if (evtId === 1) { pathos -= 5; ethos -= 3; }
                else if (evtId === 4) { pathos -= 7; }
                else if (evtId === 5) { ethos -= 4; }

                logos = Math.max(0, Math.min(100, 50 + logos));
                ethos = Math.max(0, Math.min(100, 50 + ethos));
                pathos = Math.max(0, Math.min(100, 50 + pathos));
                ethics = Math.max(0, Math.min(100, 70 + ethics));

                ces = Math.round(logos * 0.20 + ethos * 0.25 + pathos * 0.40 + ethics * 0.15);
                ds.employeeCES = ces;

            } else if (period === 3) {
                roundLabel = this._t('audience_media');

                var specScore = d.msgSpec;
                ethos += specScore * 2;
                logos += Math.round(specScore * 1.2);

                if (d.bridgeStrat === 1) { ethos += 10; ethics += 5; logos += 3; }
                else if (d.bridgeStrat === 2) { ethos -= 12; ethics -= 8; }
                else { ethos -= 6; ethics -= 3; }

                if (d.hostileResp === 2) { ethos += 12; ethics += 6; logos += 5; pathos += 4; }
                else if (d.hostileResp === 1) { ethos -= 10; ethics -= 5; pathos -= 3; }
                else { ethos += 2; logos += 3; pathos += 2; ethics += 1; }

                var mEvt = ds.randomEvent || 6;
                if (mEvt === 3) { ethos -= 5; }

                logos = Math.max(0, Math.min(100, 50 + logos));
                ethos = Math.max(0, Math.min(100, 50 + ethos));
                pathos = Math.max(0, Math.min(100, 50 + pathos));
                ethics = Math.max(0, Math.min(100, 70 + ethics));

                ces = Math.round(logos * 0.25 + ethos * 0.35 + pathos * 0.20 + ethics * 0.20);
                ds.mediaCES = ces;
            }

            ds.logosHistory.push(logos);
            ds.ethosHistory.push(ethos);
            ds.pathosHistory.push(pathos);
            ds.ethicsHistory.push(ethics);
            ds.cesHistory.push(ces);

            ds.totalCES = Math.round(ds.cesHistory.reduce(function(s, v) { return s + v; }, 0) / ds.cesHistory.length);

            if (period === 3 && ds.boardCES >= 70 && ds.employeeCES >= 70 && ds.mediaCES >= 70) {
                ds.consistencyBonus = 15;
                ds.totalCES = Math.min(100, ds.totalCES + ds.consistencyBonus);
            }

            ds.credibility = Math.round((ds.cesHistory.reduce(function(s, v) { return s + v; }, 0) / ds.cesHistory.length) * 0.8 + (ethics * 0.2));
            ds.audienceTrust = Math.round(ethos * 0.5 + pathos * 0.3 + ethics * 0.2);
            ds.ethicsScore = Math.round(ds.ethicsHistory.reduce(function(s, v) { return s + v; }, 0) / ds.ethicsHistory.length);

            this._writeScore(ds, ds.totalCES);

            return {
                period: period,
                roundLabel: roundLabel,
                logos: logos,
                ethos: ethos,
                pathos: pathos,
                ethics: ethics,
                ces: ces,
                credibility: ds.credibility,
                trust: ds.audienceTrust,
                totalCES: ds.totalCES,
                consistencyBonus: ds.consistencyBonus,
                overallScore: ds.totalCES
            };
        }

